    private BoneLordFrames() {
    }

    /** The row for this tick (held at the last). */
    public static double[] row(double[][] table, int tick) {
        return table[Math.max(0, Math.min(table.length - 1, tick))];
    }

    /** An offset (forward, up, right, from `from` in the row) put into the world for an entity turned `yaw`. */
    public static Vec3 at(LivingEntity e, float yaw, double[] r, int from) {
        double a = Math.toRadians(yaw);
        double fx = -Math.sin(a), fz = Math.cos(a);          // forward
        double rx = -Math.cos(a), rz = -Math.sin(a);         // right
        return new Vec3(e.getX() + fx * r[from] + rx * r[from + 2], e.getY() + r[from + 1],
                e.getZ() + fz * r[from] + rz * r[from + 2]);
    }
